/* v1.2: 모든 계산문제 해설을 '사용 공식 → 계산 과정 → 최종 답' 형식으로 통일한다. */
function solutionPlainText(html){
  const template=document.createElement('template');
  template.innerHTML=html||'';
  template.content.querySelectorAll('.solution-frac').forEach(frac=>{
    const num=frac.querySelector(':scope>.solution-num')?.textContent?.trim()||'';
    const den=frac.querySelector(':scope>.solution-den')?.textContent?.trim()||'';
    frac.replaceWith(document.createTextNode(`${num}/${den}`));
  });
  return template.content.textContent||'';
}

function stackedFractionText(text){
  const protectedUnits=[
    'kJ/(kg·K)','kJ/(kg·℃)','W/(m²·K)','kW/(m²·K)','W/(m·K)','m²·K/W',
    'kJ/kg(DA)','kg/kg(DA)',
    'kJ/kg','kJ/m³','kcal/h','kg/kg′','kg/kg','kg/m³','kg/s','kg/h',
    'm³/kg','m³/s','m³/h','m²/s','m/s','m/min','L/min','Pa/m','W/m²','W/m','W/K'
  ];
  let protectedText=String(text||'');
  protectedUnits.forEach((unit,index)=>{
    protectedText=protectedText.split(unit).join(`§UNIT${index}§`);
  });

  /* 안쪽 나눗셈부터 임시 토큰으로 바꿔 중첩식과 아래첨자 분수도 빠짐없이 처리한다. */
  const fractionParts=[];
  const token=String.raw`§FRAC\d+§`;
  const bare=String.raw`(?:${token}|(?!(?:ln|√)\()[\p{L}\p{N}._,₀-₉ᵢₐₑᵥ𝚌ᴸᴴ′πρληΔΣ]+)`;
  const grouped=String.raw`(?:\([^()/]*\)|\[[^\[\]/]*\]|\{[^{}\/]*\}|(?:ln|√)\([^()/]*\))`;
  const atom=String.raw`(?:${grouped}|${bare})`;
  const product=String.raw`${atom}(?:\s*×\s*${atom})*`;
  const division=new RegExp(`(${product})\\s*\\/\\s*(${atom})`,'u');
  let working=protectedText;
  let found=false;

  for(let guard=0;guard<80&&working.includes('/');guard++){
    const match=working.match(division);
    if(!match)break;
    found=true;
    const index=match.index||0;
    const key=`§FRAC${fractionParts.length}§`;
    fractionParts.push({num:match[1],den:match[2]});
    working=working.slice(0,index)+key+working.slice(index+match[0].length);
  }
  if(!found)return null;

  const restoreUnits=value=>{
    let restored=value;
    protectedUnits.forEach((unit,index)=>{
      restored=restored.split(`§UNIT${index}§`).join(unit);
    });
    return restored;
  };
  const render=value=>{
    const matcher=/§FRAC(\d+)§/g;
    let output='',lastIndex=0,match;
    while((match=matcher.exec(value))){
      output+=esc(restoreUnits(value.slice(lastIndex,match.index)));
      const part=fractionParts[Number(match[1])];
      const numerator=render(part.num);
      const denominator=render(part.den);
      const label=`${restoreUnits(part.num)} 나누기 ${restoreUnits(part.den)}`.replace(/§FRAC\d+§/g,'분수');
      output+=`<span class="solution-frac" role="math" aria-label="${esc(label)}"><span class="solution-num">${numerator}</span><span class="solution-den">${denominator}</span></span>`;
      lastIndex=matcher.lastIndex;
    }
    output+=esc(restoreUnits(value.slice(lastIndex)));
    return output;
  };
  return render(working);
}

function stackFractionsInSolutionHtml(html){
  const template=document.createElement('template');
  template.innerHTML=html||'';
  const walker=document.createTreeWalker(template.content,NodeFilter.SHOW_TEXT);
  const targets=[];
  while(walker.nextNode()){
    const node=walker.currentNode;
    if(node.parentElement?.closest('.solution-frac,.solution-unit'))continue;
    if(node.nodeValue?.includes('/'))targets.push(node);
  }
  targets.forEach(node=>{
    const converted=stackedFractionText(node.nodeValue);
    if(!converted)return;
    const holder=document.createElement('template');
    holder.innerHTML=converted;
    node.replaceWith(holder.content);
  });
  return template.innerHTML;
}

function formatSubscriptsInSolutionHtml(html){
  const template=document.createElement('template');
  template.innerHTML=html||'';
  const walker=document.createTreeWalker(template.content,NodeFilter.SHOW_TEXT);
  const targets=[];
  while(walker.nextNode()){
    const node=walker.currentNode;
    if(node.parentElement?.closest('sub,script,style'))continue;
    if(/[A-Za-zα-ωΑ-Ω]_[A-Za-z0-9]+/.test(node.nodeValue||''))targets.push(node);
  }
  targets.forEach(node=>{
    const source=node.nodeValue||'';
    const holder=document.createElement('template');
    holder.innerHTML=esc(source).replace(/([A-Za-zα-ωΑ-Ω])_([A-Za-z0-9]+)/g,'$1<sub>$2</sub>');
    node.replaceWith(holder.content);
  });
  return template.innerHTML;
}

function formatSolutionMathHtml(html){
  return formatSubscriptsInSolutionHtml(stackFractionsInSolutionHtml(formatRootsInSolutionHtml(html)));
}

function symbolDefinitionsForQuestion(question,bodyHtml){
  const text=solutionPlainText(bodyHtml).replace(/\s+/g,' ');
  const context=`${question?.title||''} ${question?.promptHtml||''} ${text}`;
  const definitions=[];
  const add=(symbol,description)=>{
    if(!definitions.some(item=>item[0]===symbol))definitions.push([symbol,description]);
  };
  const has=(pattern)=>pattern.test(text);

  if(has(/G_H|G<sub>H<\/sub>/)&&has(/G_L|G<sub>L<\/sub>/)){
    add('G_H/G_L','저단측 냉매 순환량에 대한 고단측 냉매 순환량의 비율');
    add('G_H','고단측 압축기를 통과하는 냉매 순환량');
    add('G_L','저단측 압축기를 통과하는 냉매 순환량');
  }
  if(has(/v_H/))add('v_H','고단측 압축기 흡입 냉매의 비체적');
  if(has(/v_L/))add('v_L','저단측 압축기 흡입 냉매의 비체적');
  if(has(/G_m|Gₘ/))add('G_m','중간냉각기 또는 바이패스 계통의 냉매량');
  if(has(/V_a|Vₐ/))add('V_a','압축기의 피스톤 배출량 또는 이론 흡입체적유량');
  if(has(/η_v|ηᵥ/))add('η_v','압축기의 체적효율');
  if(has(/η_c|η𝚌/))add('η_c','압축효율');
  if(has(/η_m|ηₘ/))add('η_m','기계효율');
  if(has(/L_s|Lₛ/))add('L_s','압축기 축동력');
  if(has(/L_i|Lᵢ/))add('L_i','압축기의 지시동력');
  if(has(/q_e|qₑ/))add('q_e','냉매 1 kg당 냉동효과');
  if(has(/Q_e|Qₑ/))add('Q_e','냉동장치의 냉동능력');
  if(has(/Q_c|Q𝚌|q_c/))add('Q_c','응축기 방열량 또는 냉각열량');
  if(has(/P_fan/))add('P_fan','송풍기가 발생시키는 정압');
  if(has(/η_s/))add('η_s','송풍기의 정압효율');
  if(has(/\bP[vᵥ]\b/))add('P_v','공기의 속도압(동압)');
  if(has(/\bLMTD\b/))add('LMTD','대수평균온도차');
  if(has(/\bSHF\b/))add('SHF','현열부하를 전열부하로 나눈 현열비');
  if(has(/\bCOP\b/))add('COP','냉동효과를 압축일로 나눈 성적계수');
  if(has(/\bBF\b/))add('BF','코일의 바이패스계수');
  if(has(/\bCF\b/))add('CF','코일의 접촉계수');
  if(has(/(?:h_[A-Za-z0-9]|h[₀-₉]|h[Ａ-ＺA-Z])/))add('h_1, h_2, …','각 상태점에서의 냉매 또는 공기의 비엔탈피');
  if(has(/(?:x_[A-Za-z0-9]|x[₀-₉Ａ-ＺA-Z])/))add('x_1, x_2, …','각 상태점에서의 절대습도');
  if(has(/(?:t_[A-Za-z0-9]|t[₀-₉Ａ-ＺA-Z])/))add('t_1, t_2, …','각 상태점에서의 온도');
  if(has(/(?:q_s|qₛ)/))add('q_s','현열량');
  if(has(/(?:q_l|qₗ)/))add('q_l','잠열량');
  if(has(/(?:q_t|qₜ)/))add('q_t','전열량');
  if(has(/(?:C_p|Cₚ|Cp)/))add('C_p','유체의 정압비열');
  if(has(/Δt/))add('Δt','두 지점 또는 두 유체 사이의 온도차');
  if(has(/π/))add('π','원주율');
  if(has(/ρ/))add('ρ','유체의 밀도');
  if(has(/\bK\b/)&&/열관류|열통과|열교환|전열/.test(context))add('K','열관류율 또는 열통과율');
  if(has(/\bA\b/)&&/면적|덕트|코일|전열/.test(context))add('A','면적');
  if(has(/\bG\b/)&&/냉매|공기질량|질량유량|순환량/.test(context))add('G','질량유량 또는 냉매 순환량');
  if(has(/\bv[₀-₉]|v_[A-Za-z0-9]/)&&!/v_H|v_L/.test(text))add('v_1, v_2, …','각 상태점에서 냉매의 비체적');
  if(has(/\bw\b/)&&/압축일|COP|냉동/.test(context))add('w','냉매 1 kg당 압축일');
  if(has(/P[₁-₉]|P_[A-Za-z0-9]/)&&/압력|압축비/.test(context))add('P_1, P_2, …','각 상태점의 압력');
  if(has(/\bN\b/)&&/회전|rpm|RPM|피스톤/.test(context))add('N','압축기 회전수');
  if(has(/\bz\b/)&&/기통|피스톤/.test(context))add('z','압축기의 기통수');
  if(has(/\bD\b/)&&/덕트|관경|직경|지름/.test(context))add('D','원형 덕트 또는 관의 지름');
  if(has(/λ/)&&/벽|전도|열관류|노벽/.test(context))add('λ','재료의 열전도율');
  if(has(/λ/)&&/덕트|마찰|배관/.test(context))add('λ','관 또는 덕트의 마찰계수');
  if(has(/α[ᵢₒio]?/)&&/열전달|열관류|표면/.test(context))add('α','표면 열전달률');
  if(question?.sourceId==='2025-2-rewritten-08'){
    add('ΔP_h','액관의 높이차로 생기는 압력손실');
    add('ΔP_f','액관과 부속에서 생기는 마찰 압력손실');
    add('ΔP_total','수액기에서 팽창밸브 직전까지의 전압력손실');
    add('ΔP_allow','과냉각에 의해 허용되는 압력강하');
    add('L′','직관과 부속의 상당길이를 합한 전체 상당길이');
    add('U','액관 속 냉매액의 평균속도');
    add('g','중력가속도');
    add('h','수액기 액면과 팽창밸브 사이의 높이차');
    add('P_sat','해당 온도에서 냉매의 포화압력');
  }
  return definitions;
}

function symbolDefinitionHtml(definitions){
  if(!definitions.length)return '';
  return `<div class="solution-symbol-box">${definitions.map(([symbol,description])=>
    `<div class="solution-symbol-row"><span class="solution-symbol-term">${formatSolutionMathHtml(esc(symbol))}</span><span class="solution-symbol-desc">${esc(description)}</span></div>`
  ).join('')}</div>`;
}

function formulaCandidatesFromExplanation(html){
  const template=document.createElement('template');
  template.innerHTML=html||'';
  const candidates=[];
  const usedLeft=new Set();

  template.content.querySelectorAll('.solution-step').forEach(step=>{
    const text=solutionPlainText(step.innerHTML).replace(/\s+/g,' ').trim();
    if(!text.includes('=')||/^(검산|정답)/.test(text))return;
    const parts=text.split('=').map(value=>value.trim()).filter(Boolean);
    if(parts.length<2)return;

    let left=parts[0].replace(/^[①-⑳⑴-⒇(（]?\d+[)）.]?\s*/,'').trim();
    if(left.length>42)left=left.slice(Math.max(left.lastIndexOf(' '),0)).trim()||left;
    const right=parts[1];
    if(!left||!right)return;

    const leftKey=left.replace(/\s+/g,'');
    if(usedLeft.has(leftKey))return;
    const rightWithoutUnits=right
      .replace(/(?:kg|m[²³]?|m2|m3)\/(?:s|h)|kJ\/kg/gi,'')
      .replace(/\b(?:MPa|kPa|Pa|kW|W|kJ|kg|RT)\b/gi,'')
      .replace(/\b(?:m|s|h)\b|℃|%/gi,'');
    const hasSymbolicVariable=/[A-Za-z\u0370-\u03ff]/.test(rightWithoutUnits)||/[가-힣]{2,}/.test(rightWithoutUnits);
    /* 숫자만 대입된 계산식은 기본 원식으로 올리지 않는다. */
    if(!hasSymbolicVariable)return;
    const numericProbe=rightWithoutUnits
      .replace(/[₀-₉]/g,'')
      .replace(/([A-Za-zΑ-ωα-ω])_?\d+/g,'$1');
    const allowedFormulaNumbers=new Set(['1','2','3.6','4','60','100','273','1000','3600']);
    const hasSubstitutedNumber=(numericProbe.match(/\d[\d,]*(?:\.\d+)?/g)||[])
      .map(value=>value.replace(/,/g,''))
      .some(value=>!allowedFormulaNumbers.has(value));
    /* 변수식에 문제 수치가 섞인 경우도 기본 원식에서 제외한다. */
    if(hasSubstitutedNumber)return;
    const hasRelation=/[×/＋+−\-√]|ln\(|\b(?:h|q|Q|G|V|A|K|R|COP|SHF|CLTD|LMTD|P|v|d|t|x|η|λ|ρ|π|Δ)\b/i.test(right);
    if(!hasRelation&&candidates.length)return;

    usedLeft.add(leftKey);
    candidates.push(`${left} = ${right}`);
  });
  return candidates.slice(0,20);
}

