  const extracted=formulaOnlySourceIds.has(question.sourceId)?[]:formulaCandidatesFromExplanation(bodyHtml);
  const combined=[...foundations,...extracted];
  const used=new Set();
  return combined.filter(formula=>{
    const key=solutionPlainText(formula).replace(/\s+/g,'');
    if(!key||used.has(key))return false;
    used.add(key);
    return true;
  });
