function displayAnswerUnit(field){
  const units=Array.isArray(field?.units)?field.units:(field?.units?[field.units]:[]);
  const raw=units.find(unit=>String(unit).trim())||'';
  const key=String(raw).toLowerCase();
  const known={
    'kw':'kW','w':'W','kj/kg':'kJ/kg','kjkg':'kJ/kg','m2':'m²','m³/s':'m³/s','m3/s':'m³/s',
    'm³/h':'m³/h','m3/h':'m³/h','kg/s':'kg/s','kg/h':'kg/h','rt':'RT','pa':'Pa','kpa':'kPa',
    'mpa':'MPa','℃':'℃','c':'℃','mm':'mm','m':'m','%':'%'
  };
  return known[key]||raw;
}

function finalAnswerHtml(question){
  const fields=(question.fields||[]).filter(field=>field&&field.v!==undefined&&field.v!==null);
  if(!fields.length)return '';
  return `<div class="solution-final-box">${fields.map(field=>{
    const value=typeof field.v==='number'
      ?field.v.toLocaleString('en-US',{maximumFractionDigits:10,useGrouping:true})
      :String(field.v);
    const unit=displayAnswerUnit(field);
    return `<div class="solution-final-row">${esc(field.label||'정답')} = ${esc(value)}${unit?' '+esc(unit):''}</div>`;
  }).join('')}</div>`;
}

function enhanceCalculationExplanation(question){
  if(!question||question._formulaExplanationV12||!/(calc|mixed|duct_table|compare_table)/.test(question.type||''))return;
  let original=question.explanationHtml||'';
  if(!original&&question.explanation){
    original=SH('[자체 해설]')+String(question.explanation).split(/\n+/).filter(Boolean).map(line=>SL(esc(line))).join('');
  }
  if(!original)return;

  const headingMatch=original.match(/^<div class="solution-heading">[\s\S]*?<\/div>/);
  const titleHeading=headingMatch?headingMatch[0]:SH('[해설]');
  const body=headingMatch?original.slice(headingMatch[0].length):original;
  const formulas=formulaGuideForQuestion(question,body);
  const symbols=symbolDefinitionsForQuestion(question,body);
  const formulaHtml=formulas.length
    ?formulas.map(formula=>formula.includes('solution-frac')?SL(formula):SL(esc(formula))).join('')
    :SL('문제에 제시된 조건의 관계를 먼저 세운 뒤 구하려는 값이 왼쪽에 오도록 식을 정리한다.');

  const symbolSection=symbols.length
    ?SH('1. 기호 뜻')+symbolDefinitionHtml(symbols)
    :'';
  const formulaStep=symbols.length?'2. 기본 원식과 식 정리':'1. 기본 원식과 식 정리';
  const calculationStep=symbols.length?'3. 수치 대입 및 계산':'2. 수치 대입 및 계산';
  const answerStep=symbols.length?'4. 최종 답':'3. 최종 답';

  const calculationHtml=formatSolutionMathHtml(body);

  question.explanationHtml=
    titleHeading+
    symbolSection+
    SH(formulaStep)+
    `<div class="solution-formula-box"><div class="solution-derivation-note">기본 원식을 먼저 세우고, 구하려는 값이 왼쪽에 남도록 양변에 같은 계산을 적용하여 순서대로 정리한다.</div>${formatSolutionMathHtml(formulaHtml)}</div>`+
    SH(calculationStep)+
    `<div class="solution-calc-box">${calculationHtml}</div>`+
    SH(answerStep)+
    finalAnswerHtml(question);
  question._formulaExplanationV12=true;
}

