// v151: 모의고사 1~6의 냉동 분야 문제를 빠른 문제풀이 '냉동'에 통합
const mockRefrigerationSelections = {"1": [1, 5, 8, 9, 10, 14], "2": [3, 6, 8, 10, 11, 13, 14], "3": [1, 5, 6, 7, 10, 13], "4": [2, 3, 6, 10, 13], "5": [2, 3, 5, 6, 7, 9, 13], "6": [2, 4, 5, 7, 8, 11, 12]};
const refrigerationDescriptiveQuestions = [];
const mockExamQuestionSets = {
  1: fullExamQuestions,
  2: mock2Questions,
  3: mock3Questions,
  4: mock4Questions,
  5: mock5Questions,
  6: mock6Questions,
  7: mock7Questions
};

Object.entries(mockRefrigerationSelections).forEach(([mockNo, questionIds]) => {
  const sourceSet = mockExamQuestionSets[mockNo] || [];
  questionIds.forEach(questionId => {
    const original = sourceSet.find(question => Number(question.id) === Number(questionId));
    if (!original) return;

    const targetQuestions = original.type === 'desc'
      ? refrigerationDescriptiveQuestions
      : refrigerationPracticeQuestions;
    const targetCategory = original.type === 'desc' ? '서술형' : '냉동';
    const targetSource = original.type === 'desc' ? 'descriptive' : 'refrigeration';

    targetQuestions.push({
      ...original,
      sourceId: `quick-${targetSource}-mock${mockNo}-q${questionId}`,
      category: targetCategory,
      title: `[모의고사 ${mockNo}] ${original.title}`
    });
  });
});

// v157: 고정된 냉동 문제 순서에서 작도·비교·혼합형 9문제를 서술형 메뉴로 이동
const refrigerationMoveToDescriptiveIndexes = new Set([12,17,18,22,25,26,28,32,33]);
const movedRefrigerationQuestions = refrigerationPracticeQuestions
  .filter((question, index) => refrigerationMoveToDescriptiveIndexes.has(index + 1))
  .map(question => ({...question, category:'서술형'}));

for(let index=refrigerationPracticeQuestions.length-1;index>=0;index--){
  if(refrigerationMoveToDescriptiveIndexes.has(index + 1)){
    refrigerationPracticeQuestions.splice(index,1);
  }
}
refrigerationDescriptiveQuestions.push(...movedRefrigerationQuestions);


