function startRefrigerationPractice(event){
  if(event)event.preventDefault();
  const selected=refrigerationPracticeQuestions.map((q,i)=>({...q,id:i+1}));

  if(selected.length!==30){
    showMenuNotice({preventDefault(){}},'냉동 문제 일부를 불러오지 못했습니다.');
    return;
  }

  resetQuestionSession(selected,'빠른문제 냉동');
  showSiteView(null,'exam');
}
function startSingleQuickPractice(event,sourceId,title){
  if(event)event.preventDefault();

  const sourcePool=[
    ...mock2Questions,
    ...mock3Questions,
    ...mock4Questions,
    ...mock5Questions,
    ...mock6Questions,
    ...mock7Questions
  ];

  const source=sourcePool.find(q=>q.sourceId===sourceId);

  if(!source){
    showMenuNotice({preventDefault(){}},title+' 문제를 불러오지 못했습니다.');
    return;
  }

  const selected=[{...source,id:1}];
  resetQuestionSession(selected,'빠른문제 '+title);
  showSiteView(null,'exam');
}

