function showPracticeCategory(event,name){
  if(event)event.preventDefault();
  if(name==='냉동'){startRefrigerationPractice(null);return}
  if(name==='공기조화'){startAirConditioningPractice(null);return}
  if(name==='냉난방부하'){startCoolingHeatingLoadPractice(null);return}
  if(name==='덕트·송풍기'){startDuctBlowerPractice(null);return}
  if(name==='서술형'){startDescriptivePractice(null);return}
  showSiteView(null,'practice');
  setTimeout(()=>showMenuNotice({preventDefault(){}},name+' 문제'),80);
}
function closeDropdowns(except){
  document.querySelectorAll('.nav-group.open').forEach(group=>{
    if(group!==except){group.classList.remove('open');const trigger=group.querySelector('.nav-trigger');if(trigger)trigger.setAttribute('aria-expanded','false')}
  });
}
function toggleDropdown(event,button){
  event.preventDefault();event.stopPropagation();
  const group=button.closest('.nav-group');
  const willOpen=!group.classList.contains('open');
  closeDropdowns(group);
  group.classList.toggle('open',willOpen);
  button.setAttribute('aria-expanded',String(willOpen));
}
function toggleSiteMenu(button){
  const menu=document.getElementById('siteMenu');
  const open=menu.classList.toggle('open');
  button.setAttribute('aria-expanded',String(open));
  button.setAttribute('aria-label',open?'전체 메뉴 닫기':'전체 메뉴 열기');
  button.textContent=open?'×':'☰';
}
function closeSiteMenu(){
  const menu=document.getElementById('siteMenu');
  const button=document.querySelector('.menu-toggle');
  if(menu) menu.classList.remove('open');
  if(button){button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','전체 메뉴 열기');button.textContent='☰'}
  closeDropdowns();
}
function showSiteView(event,view){
  if(event)event.preventDefault();
  if(typeof closeInfoPage==='function'&&document.querySelector('.info-page.show'))closeInfoPage(null);
  document.body.classList.toggle('view-home',view==='home');
  document.body.classList.toggle('view-exam',view==='exam');
  document.body.classList.toggle('view-practice',view==='practice');
  document.body.classList.toggle('view-learning',view==='learning');
  document.querySelectorAll('[data-view-link]').forEach(link=>{link.classList.remove('active');link.removeAttribute('aria-current')});
  const active=document.querySelector('[data-view-link="'+view+'"]');
  if(active){active.classList.add('active');active.setAttribute('aria-current','page')}
  closeSiteMenu();
  history.replaceState(null,'',view==='home'?'#home':view==='practice'?'#practice':view==='learning'?'#learning-heat':'#examTop');
  if(event&&view==='home')trackVirtualPage('/','홈');
  if(event&&view==='practice')trackVirtualPage('/practice','빠른 문제풀이');
  window.scrollTo({top:0,behavior:'smooth'});
}
function showLearningTopic(event,topic){
  if(event)event.preventDefault();
  const target=document.querySelector('[data-learning-topic="'+topic+'"]');
  if(!target){showMenuNotice({preventDefault(){}},'해당 학습자료');return}
  document.querySelectorAll('[data-learning-topic]').forEach(section=>section.hidden=section!==target);
  showSiteView(null,'learning');
  const hashMap={
    fundamentals:'#learning-fundamentals',
    terms:'#learning-terms',
    refrigeration:'#learning-refrigeration',
    equipment:'#learning-equipment',
    load:'#learning-load',
    airconditioning:'#learning-airconditioning',
    heat:'#learning-heat'
  };
  history.replaceState(null,'',hashMap[topic]||'#learning-heat');
  if(event){
    const topicTitle=target.querySelector('h1')?.textContent.trim()||topic;
    trackVirtualPage('/learning/'+topic,topicTitle);
    sendAnalyticsEvent('learning_material_view',{topic_name:topicTitle,topic_id:topic});
  }
  setTimeout(()=>target.scrollIntoView({behavior:'smooth',block:'start'}),60);
}
function showMenuNotice(event,name){
  event.preventDefault();
  closeSiteMenu();
  const notice=document.getElementById('menuNotice');
  notice.textContent=name+' 페이지는 다음 단계에서 연결할 예정입니다.';
  notice.classList.add('show');
  clearTimeout(menuNoticeTimer);
  menuNoticeTimer=setTimeout(()=>notice.classList.remove('show'),1800);
}
function setHomeDemoPlaybackRate(){
  document.querySelectorAll('.home-demo-video').forEach(video=>{
    video.defaultPlaybackRate=3;
    video.playbackRate=3;
  });
}
const homeDemoVideos=document.querySelectorAll('.home-demo-video');
setHomeDemoPlaybackRate();
homeDemoVideos.forEach(video=>{
  video.addEventListener('loadedmetadata',setHomeDemoPlaybackRate);
  video.addEventListener('play',setHomeDemoPlaybackRate);
});
document.addEventListener('click',function(event){
  if(!event.target.closest('.nav-group')) closeDropdowns();
  if(!event.target.closest('.site-header')) closeSiteMenu();
});
window.addEventListener('resize',function(){if(window.innerWidth>960) closeSiteMenu()});
(function setInitialSiteView(){
  const hash=location.hash.slice(1);
  if(hash==='examTop')showSiteView(null,'exam');else if(hash==='practice'||hash==='randomPractice')showSiteView(null,'practice');else if(hash==='learning-terms')showLearningTopic(null,'terms');else if(hash==='learning-heat')showLearningTopic(null,'heat');else if(hash==='learning-refrigeration')showLearningTopic(null,'refrigeration');else if(hash==='learning-equipment')showLearningTopic(null,'equipment');else if(!['privacy','terms','contact','copyright','about','guide','grading','updates','faq'].includes(hash))showSiteView(null,'home');
})();
